export function maxTreeDepth(root) {
    if (root == null)
        return 0;
    const queue = [root];
    let head = 0, depth = 0;
    while (head < queue.length) {
        const count = queue.length - head;
        for (let i = 0; i < count; i++) {
            const node = queue[head++];
            if (node.left != null)
                queue.push(node.left);
            if (node.right != null)
                queue.push(node.right);
        }
        depth++;
    }
    return depth;
}
